import { useEffect, useMemo, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from 'framer-motion'
import { Factory, Heart, Menu, MessageCircle, Minus, Plus, Ruler, Search, Shirt, ShoppingBag, SlidersHorizontal, Star, X, ZoomIn } from 'lucide-react'
import { cities, customerPhotos, featuredEid, formatPrice, getProduct, placeholderBlur, products, type Product } from '@/lib/mock-data'
import { cartTotal, useCart } from '@/lib/cart-store'
